def get_divisors(n):
    divs = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def tau(n):
    return len(get_divisors(n))

results = []

for n in range(10, 201):
    if tau(n) >= 5:
        divisors = get_divisors(n)

        # Since tau(n) >= 5, we are guaranteed to have at least 5 divisors.
        # Divisors are 1, d2, d3, d4, d5, ...

        # Second smallest divisor (a)
        a = divisors[1] 
        # Third smallest divisor (b)
        b = divisors[2]
        # Fifth smallest divisor (c)
        c = divisors[4]

        # Check the condition: n = ab + ac + bc
        check = a * b + a * c + b * c

        if check == n:
            results.append((n, tau(n)))

print("N_satisfying_condition = ", results)
